{
  "critique": [
    {
      "design": "r0A",
      "good": "CVE IDs and package names stay intact, version ranges have room to wrap, and the headers remain on one line. The 260px summary column avoids mid-word splits.",
      "problems": "The initial viewport shows the ID and package but only a sliver of the version column. Readers must scroll considerably to assess severity and impact. Tall summary-driven rows also leave large empty areas under the short identification fields.",
      "cause": "The 146px and 183px first columns consume 329px before affected versions begin. The 260px summary still requires many lines, while the full table is 850px wide."
    },
    {
      "design": "r0B",
      "good": "More of the affected-version column is visible initially, and the narrower table reduces horizontal travel. CVE IDs remain intact.",
      "problems": "Package names break across lines, including the path-like name, while the narrow summary makes rows much taller and increases the separation between advisories. Severity and the summary still require scrolling.",
      "cause": "The 125px package column provides only 104px for text, less than the 162px needed for the longest unbreakable name. The 160px summary provides 139px of text width, well below its longest unbreakable word."
    },
    {
      "design": "r0C",
      "good": "All five columns are within the viewport, so their order and relationship are immediately visible.",
      "problems": "Identifiers, package names, version expressions and summaries fragment heavily. Extremely tall rows make it hard to scan or compare advisories, and most headers wrap.",
      "cause": "Widths of 65–76px leave only 44–55px for text in each column. In particular, the 68px summary column forces extensive word splitting and drives the table's height."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "readable-summary",
      "widths": [146, 183, 140, 80, 320],
      "change": "Refine r0A by giving the summary more room to reduce row height, while narrowing affected versions so constraints can wrap between terms. IDs, package names and severity retain their full text widths."
    },
    {
      "name": "compact-scroll",
      "widths": [146, 183, 105, 80, 241],
      "change": "Keep IDs and package names intact while using the minimum summary width needed for its longest unbreakable word. The narrower version column trades more constraint wrapping for less horizontal scrolling."
    },
    {
      "name": "earlier-versions",
      "widths": [105, 183, 140, 80, 300],
      "change": "Allow CVE IDs to wrap at their existing hyphens so more of the package and version area appears in the initial viewport. Preserve package names and give the summary enough width for natural word wrapping."
    }
  ]
}
